-- Explainable score history: the score, every factor and the evidence behind it.
create table careercloud.score_snapshots (
  id                     text primary key check (id ~ '^scs_[0-9a-f]{32}$'),
  workspace_id           uuid not null references careercloud.workspaces (id) on delete cascade,
  created_at             timestamptz not null default now(),
  updated_at             timestamptz not null default now(),
  created_by             uuid,
  version                integer not null default 1,
  entity_type            text not null default 'company' check (entity_type in ('company', 'contact')),
  entity_id              text not null check (char_length(entity_id) <= 40),
  kind                   text not null default 'account' check (kind in ('account', 'contact', 'hiring', 'technology', 'opportunity', 'buying_stage')),
  score                  double precision check (score >= 0 and score <= 100),
  label                  text check (char_length(label) <= 60),
  factors                jsonb not null default '[]'::jsonb,
  evidence               jsonb not null default '[]'::jsonb,
  model                  text not null check (char_length(model) <= 60),
  computed_at            timestamptz not null
);

