-- ---------------------------------------------------------------------------
-- Tenancy: the manager role (writes like a member, manages teams/assignment).
-- ---------------------------------------------------------------------------

alter table careercloud.workspace_members drop constraint workspace_members_role_check,
  add constraint workspace_members_role_check check (role in ('owner', 'admin', 'manager', 'member', 'viewer'));

create or replace function careercloud.can_write(ws uuid) returns boolean
  language sql stable
  as $fn$ select coalesce(careercloud.member_role(ws) in ('owner', 'admin', 'manager', 'member'), false) $fn$;

-- ---------------------------------------------------------------------------
-- Supabase's anonymous role gets nothing in this schema.
-- ---------------------------------------------------------------------------

do $anon$
begin
  if exists (select 1 from pg_roles where rolname = 'anon') then
    revoke all on all tables in schema careercloud from anon;
    revoke all on all functions in schema careercloud from anon;
  end if;
end
$anon$;
